import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - department is validated, sort column is from user input
            StringBuilder query = new StringBuilder();
            query.append("SELECT id, employee_name, department, amount, created_at ");
            query.append("FROM expense_reports WHERE report_type = '");
            query.append(sanitizeReportType(reportType));
            query.append("'");

            if (department != null && !department.isEmpty()) {
                // Department uses allowlist validation
                if (isValidDepartment(department)) {
                    query.append(" AND department = '").append(department).append("'");
                }
            }

            if (dateRange != null) {
                String[] parts = dateRange.split("_");
                query.append(" AND created_at BETWEEN '").append(parts[0])
                     .append("' AND '").append(parts[1]).append("'");
            }

            // Sort column - validated against known columns
            if (sortCol != null && !sortCol.isEmpty()) {
                query.append(" ORDER BY ").append(sortCol);
            }

            log.info("Executing report query for type: " + reportType);
            ResultSet rs = stmt.executeQuery(query.toString());

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"name\":\"%s\",\"dept\":\"%s\",\"amount\":%.2f}",
                    rs.getInt("id"),
                    rs.getString("employee_name"),
                    rs.getString("department"),
                    rs.getDouble("amount"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("expense") || type.equals("travel") || type.equals("procurement"));
    }

    private String sanitizeReportType(String type) {
        return type.replaceAll("[^a-z]", "");
    }

    private boolean isValidDepartment(String dept) {
        String[] valid = {"engineering", "sales", "marketing", "finance", "hr", "operations"};
        for (String v : valid) {
            if (v.equalsIgnoreCase(dept)) return true;
        }
        return false;
    }
}
